import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { expect, test, type Page } from '@playwright/test';
import { PNG } from 'pngjs';
import { addSpaceBackground } from './support/spaceBackground.js';
import { openSection } from './support/accordion.js';

const SPEC_DIR = path.dirname(fileURLToPath(import.meta.url));
// v2-release R1 (follow-up): switched from local-only `tmp/quad-debug/` (gitignored,
// generated by scripts/measure-portable-screen-quad.mjs) to the committed fixture at
// `e2e/fixtures/portable-screen-quads.json` so CI can resolve it. This mirrors the K1
// spec fix (v2-S5 보완 A1 / 2026-10-13).
const JSON_PATH = path.resolve(SPEC_DIR, 'fixtures', 'portable-screen-quads.json');

// v2-S5 K2. Portable content Fit (contain) letterboxes within the preset screen quad.
// The quad's apparent aspect comes from `tmp/quad-debug/portable-screen-quads.json` (same
// source of truth K1 uses) so this test cannot drift from the measured quad.
//
// For a 16:9 content image in a quad of apparent aspect `a_q`:
//   - If a_q > 16/9 (quad wider than content): pillarbox left/right.
//     Content occupies horizontal fraction = (16/9) / a_q.
//   - If a_q < 16/9 (quad narrower than content, i.e. quad taller/skinnier):
//     letterbox top/bottom. Content occupies vertical fraction = a_q / (16/9).
//   - If a_q == 16/9: content fills the quad with no bars.
//
// Gate: measured bar fraction within ±1 % of the expected value, for each of the 3 views.

test.use({ locale: 'ja-JP' });

type NormalizedQuad = {
  topLeft: { x: number; y: number };
  topRight: { x: number; y: number };
  bottomRight: { x: number; y: number };
  bottomLeft: { x: number; y: number };
};

type ViewName = 'front' | 'angled-left' | 'angled-right';

async function loadQuads(): Promise<Record<ViewName, NormalizedQuad>> {
  const buf = await fs.readFile(JSON_PATH, 'utf8');
  const parsed = JSON.parse(buf) as { views: Record<ViewName, { normalized: NormalizedQuad }> };
  return {
    front: parsed.views['front'].normalized,
    'angled-left': parsed.views['angled-left'].normalized,
    'angled-right': parsed.views['angled-right'].normalized,
  };
}

function quadApparentAspect(q: NormalizedQuad, objW: number, objH: number): number {
  const local = {
    topLeft: { x: q.topLeft.x * objW, y: q.topLeft.y * objH },
    topRight: { x: q.topRight.x * objW, y: q.topRight.y * objH },
    bottomRight: { x: q.bottomRight.x * objW, y: q.bottomRight.y * objH },
    bottomLeft: { x: q.bottomLeft.x * objW, y: q.bottomLeft.y * objH },
  };
  const t = Math.hypot(local.topRight.x - local.topLeft.x, local.topRight.y - local.topLeft.y);
  const b = Math.hypot(
    local.bottomRight.x - local.bottomLeft.x,
    local.bottomRight.y - local.bottomLeft.y,
  );
  const l = Math.hypot(local.bottomLeft.x - local.topLeft.x, local.bottomLeft.y - local.topLeft.y);
  const r = Math.hypot(
    local.bottomRight.x - local.topRight.x,
    local.bottomRight.y - local.topRight.y,
  );
  return (t + b) / 2 / ((l + r) / 2);
}

async function solid16x9Png(page: Page, color: string): Promise<Buffer> {
  // 1600×900 — explicit 16:9 so the apparent-aspect math is pinned.
  const arr = (await page.evaluate(
    ({ color }) => {
      const w = 1600;
      const h = 900;
      const canvas = document.createElement('canvas');
      canvas.width = w;
      canvas.height = h;
      const ctx = canvas.getContext('2d')!;
      ctx.fillStyle = color;
      ctx.fillRect(0, 0, w, h);
      const dataUrl = canvas.toDataURL('image/png');
      const bin = atob(dataUrl.split(',')[1]!);
      const arr = new Uint8Array(bin.length);
      for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
      return Array.from(arr);
    },
    { color },
  )) as number[];
  return Buffer.from(arr);
}

async function setupPortableWithContent(page: Page, view: ViewName): Promise<void> {
  await page.goto('/');
  await addSpaceBackground(page, { width: 1920, height: 1080, color: '#334455' });
  await page.getByTestId('editor-add-portable').click();
  await openSection(page, 'appearance');
  const viewSelect = page.getByLabel(/ビュー|View|뷰/);
  const current = await viewSelect.inputValue();
  if (current !== view) await viewSelect.selectOption(view);
  await openSection(page, 'content');
  const magenta = await solid16x9Png(page, '#ff00ff');
  await page.getByTestId('editor-content-upload').setInputFiles({
    name: 'content-16x9.png',
    mimeType: 'image/png',
    buffer: magenta,
  });
  // Set fit = contain (editor-content-fit selector).
  const fitSelect = page.getByRole('combobox', { name: '表示方法' });
  await fitSelect.selectOption('contain');
  // Zero LCD highlight so the sample pixels aren't tinted.
  await openSection(page, 'appearance');
  const intensity = page.getByRole('slider', { name: '質感の強さ' });
  await intensity.focus();
  await intensity.press('Home');
  await intensity.press('Tab');
}

async function exportPng(page: Page): Promise<PNG> {
  const dl = page.waitForEvent('download');
  await page.getByTestId('editor-export-png-header').click();
  const d = await dl;
  const buffer = await fs.readFile((await d.path())!);
  return PNG.sync.read(buffer);
}

function countMagentaOnRay(
  png: PNG,
  centerX: number,
  centerY: number,
  dx: number,
  dy: number,
  maxSteps: number,
): number {
  // Walk along (dx, dy) direction from the center, counting pixels that are magenta.
  // Returns the step count up to which the walk stays magenta.
  let steps = 0;
  for (let s = 1; s < maxSteps; s++) {
    const x = Math.round(centerX + dx * s);
    const y = Math.round(centerY + dy * s);
    if (x < 0 || x >= png.width || y < 0 || y >= png.height) break;
    const i = (y * png.width + x) * 4;
    const r = png.data[i]!;
    const g = png.data[i + 1]!;
    const b = png.data[i + 2]!;
    if (r > 200 && g < 60 && b > 200) steps = s;
    else break;
  }
  return steps;
}

// Default portable: object (762, 243, 396, 594) at docOrigin, rotation 0.
const PORTABLE_OBJECT = { x: 762, y: 243, width: 396, height: 594, rotation: 0 };

for (const view of ['front', 'angled-left', 'angled-right'] as const) {
  test(`K2 ${view}: 16:9 content Fit letterbox ratio within ±1%`, async ({ page }) => {
    const quads = await loadQuads();
    const quad = quads[view];
    await setupPortableWithContent(page, view);
    const png = await exportPng(page);

    // Expected ratio: compare quad aspect (object-local) with content aspect (16/9).
    const aQ = quadApparentAspect(quad, PORTABLE_OBJECT.width, PORTABLE_OBJECT.height);
    const aC = 16 / 9;
    const contentFracExpected = aC > aQ ? aQ / aC : aC / aQ;
    // Quad centroid in doc coords.
    const centroidNorm = {
      x: (quad.topLeft.x + quad.topRight.x + quad.bottomRight.x + quad.bottomLeft.x) / 4,
      y: (quad.topLeft.y + quad.topRight.y + quad.bottomRight.y + quad.bottomLeft.y) / 4,
    };
    const centroidDoc = {
      x: PORTABLE_OBJECT.x + centroidNorm.x * PORTABLE_OBJECT.width,
      y: PORTABLE_OBJECT.y + centroidNorm.y * PORTABLE_OBJECT.height,
    };
    // Walk magenta runs from the centroid along +X, −X, +Y, −Y.
    const posX = countMagentaOnRay(png, centroidDoc.x, centroidDoc.y, 1, 0, 300);
    const negX = countMagentaOnRay(png, centroidDoc.x, centroidDoc.y, -1, 0, 300);
    const posY = countMagentaOnRay(png, centroidDoc.x, centroidDoc.y, 0, 1, 300);
    const negY = countMagentaOnRay(png, centroidDoc.x, centroidDoc.y, 0, -1, 300);
    const magentaWidth = posX + negX;
    const magentaHeight = posY + negY;
    const magentaAspect = magentaWidth / magentaHeight;
    // Content aspect in the warped frame should match 16:9 ≈ 1.778.
    const contentAspectErr = Math.abs(magentaAspect - aC) / aC;
    console.log(
      `K2 ${view}: quadAspect=${aQ.toFixed(3)} contentFracExpected=${contentFracExpected.toFixed(3)} ` +
        `magenta runs @centroid=(${centroidDoc.x.toFixed(0)},${centroidDoc.y.toFixed(0)}): ` +
        `W=${magentaWidth} H=${magentaHeight} aspect=${magentaAspect.toFixed(3)} err%=${(contentAspectErr * 100).toFixed(2)}`,
    );
    // Gate: content aspect within ±1% of 16/9. This is a stronger version of the Fit
    // letterbox invariant — the magenta rectangle must preserve 16:9 aspect regardless
    // of the quad's own aspect (contain fit).
    expect(contentAspectErr).toBeLessThanOrEqual(0.01);
  });
}
